const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const calendarId = source.calendarId || payload.calendarId || 'primary';
const now = new Date();
now.setDate(now.getDate() + 1);
const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}T00:00:00+07:00`;
const end = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}T23:59:59+07:00`;
return [{ json: { ...source, payload, message, chatId, calendarId, after: start, before: end, heading: 'Lịch ngày mai' } }];

function toDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}
function formatDate(date) {
  return new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: '2-digit', month: '2-digit', year: 'numeric' }).format(date);
}
function formatTime(date) {
  return new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit', hour12: false }).format(date);
}
function formatRange(startValue, endValue) {
  const startDate = toDate(startValue);
  const endDate = toDate(endValue);
  if (!startDate) return startValue || '';
  if (!endDate) return `${formatTime(startDate)}, ${formatDate(startDate)}`;
  const sameDay = startDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' }) === endDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
  if (sameDay) return `${formatTime(startDate)} - ${formatTime(endDate)}, ${formatDate(startDate)}`;
  return `${formatTime(startDate)}, ${formatDate(startDate)} → ${formatTime(endDate)}, ${formatDate(endDate)}`;
}
function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}
const source = $('Chuan Bi Lich Ngay Mai').item.json;
const rows = $input.all().map(item => item.json || {}).filter((event) => event && Object.keys(event).length > 0 && (event.id || event.summary || event.start || event.end));
let text = `📅 <b>${escapeHtml(source.heading)}</b>\n\n`;
if (rows.length === 0) {
  text += 'Không có lịch nào trong ngày mai.';
} else {
  for (let i = 0; i < rows.length; i++) {
    const event = rows[i];
    const title = event.summary || 'Không có tiêu đề';
    const start = event.start?.dateTime || event.start?.date || '';
    const end = event.end?.dateTime || event.end?.date || '';
    const link = event.htmlLink || '';
    text += `<b>${i + 1}. ${escapeHtml(title)}</b>\n🕒 ${formatRange(start, end)}`;
    if (link) text += `\n🔗 <a href="${escapeHtml(link)}">Link</a>`;
    text += '\n\n';
  }
}
return [{ json: { chatId: source.chatId, text: text.trim() } }];
